{
  "findings": [
    {
      "check_id": "CKV_AWS_54",
      "title": "Ensure S3 bucket has block public policy enabled",
      "resource": "aws_s3_bucket_policy.pass3",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket policy does not explicitly block public access. This could lead to unintended public exposure of the bucket's contents."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket_policy.pass3",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a Public Access Block configuration, which is necessary to prevent public access at the bucket level."
    }
  ],
  "patched_code": "resource "aws_s3_bucket_policy" "pass3" {
  bucket = "bucket"

  policy = <<POLICY
        {
            "Id": "Policy1597273448050",
            "Version": "2012-10-17",
            "Statement": [
                {
                    "Sid": "Stmt1597273446725",
                    "Action": [
                        "s3:GetObject"
                    ],
                    "Resource": "arn:aws:s3:::bucket/*",
                    "Principal": {
                        "AWS": "some_arn"
                    },
                    "Effect": "Deny"
                }
            ]
        }
        POLICY
}

resource "aws_s3_bucket_public_access_block" "pass3" {
  bucket = "bucket"

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}",
  "fix_summary": "Added an `aws_s3_bucket_public_access_block` resource to ensure public access is blocked at the bucket level and public policies are restricted."
}
